package com.campusmart.entity;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Entity @Table(name="orders") public class Order {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private User buyer;@Column(nullable=false,precision=12,scale=2) private BigDecimal total;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status=Status.PENDING;private LocalDateTime createdAt=LocalDateTime.now();@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true)private List<OrderItem>items=new ArrayList<>();public enum Status{PENDING,CONFIRMED,PROCESSING,SHIPPED,DELIVERED,CANCELLED}public Long getId(){return id;}public User getBuyer(){return buyer;}public void setBuyer(User v){buyer=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}public Status getStatus(){return status;}public void setStatus(Status v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}public List<OrderItem>getItems(){return items;}}
